  const SLOTS = [{ x: 345, y: 344, s: 0.5 }, { x: 440, y: 342, s: 0.46 }, { x: 625, y: 334, s: 0.42 }, { x: 775, y: 340, s: 0.44 }, { x: 885, y: 354, s: 0.5 }];
